grid=[row+[6]*(25-len(row)) for row in grid]
R,C=25,25; seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==6 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   p=q.pop(); comp.append(p)
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     nr,nc=p[0]+dr,p[1]+dc
     if 0<=nr<R and 0<=nc<C and grid[nr][nc]==col and (nr,nc) not in seen:
      seen.add((nr,nc));q.append((nr,nc))
  comps.append((col,comp))
[(col,len(ps),(min(r for r,c in ps),max(r for r,c in ps),min(c for r,c in ps),max(c for r,c in ps)),sum(r for r,c in ps)/len(ps)) for col,ps in comps]
